<?php
namespace App\Http\Controllers; use App\Http\Requests\UpdateProgressRequest; use App\Models\Order; use App\Services\OrderService; use Illuminate\Http\RedirectResponse; class ProgressController extends Controller { public function store(UpdateProgressRequest $request, Order $order, OrderService $service): RedirectResponse { $path = $request->file('file')?->store("orders/{$order->id}/progress", 'private'); $service->recordProgress($order, $request->user(), (int)$request->input('progress_percentage'), $request->input('note'), $path); return back()->with('success','Progress update published.'); } }
